practice_tasks.solution:
def normalize_trace(raw_trace: dict) -> dict:
    canonical = {
        'system_prompt': raw_trace.get('system', ''),
        'tool_schema': raw_trace.get('tools', []),
        'terminal_state': raw_trace.get('final_output', ''),
        'ordered_message_list': []
    }
    for msg in raw_trace.get('messages', []):
        if not msg.get('is_retry_noise', False):
            canonical['ordered_message_list'].append(msg)
    return canonical

